(function(C){C["21a"]=(C["21a"]||[]).concat([{"q": "For every circle, what is the length around divided by the length across?", "a": "π", "w": ["π/2", "2π", "it depends on the circle"], "why": "Round-quotient: every circle is the circle of radius 1 pulled by its radius, and the pull multiplies both lengths alike."}, {"q": "What is L(−1), the arc of the circle of radius 1 from (1, 0) to (−1, 0)?", "a": "π", "w": ["π/2", "2π", "1"], "why": "L runs from L(−1) = π down to L(1) = 0. The half circle has the length π, and the whole circle 2π."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["21b"]=(C["21b"]||[]).concat([{"q": "What are cos θ and sin θ?", "a": "the coordinates of the point reached by walking θ round the circle of radius 1 from (1, 0)", "w": ["the two shorter sides of any triangle", "the length and the width of an arc", "the slope and the height of a line"], "why": "(cos θ, sin θ) is that point: cos is how far across, and sin is how far up."}, {"q": "cos 2π = cos 0. Does 2π = 0 follow?", "a": "no: cos repeats, so equal values do not give equal arcs", "w": ["yes, as arcs", "yes", "no: cos 2π is not cos 0"], "why": "Whole-turns: adding a whole turn changes neither coordinate."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["21c"]=(C["21c"]||[]).concat([{"q": "In which quarter are cos θ < 0 and sin θ > 0?", "a": "the second", "w": ["the first", "the third", "the fourth"], "why": "Left of the upright axis and above the floor."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["21d"]=(C["21d"]||[]).concat([{"q": "Is cos(A + B) = cos A + cos B?", "a": "no: with A = B = π/3 the left side is −1/2 and the right side is 1", "w": ["no: it is cos A cos B + sin A sin B", "yes, for small arcs", "yes"], "why": "Sum technique: cos(A + B) = cos A cos B − sin A sin B."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["21f"]=(C["21f"]||[]).concat([{"q": "As h heads to 0, to which real does sin h / h head?", "a": "1", "w": ["to none: it is 0/0", "π", "0"], "why": "Sine-over-arc: sin h / h sits between cos h and 1, and cos h heads to 1."}, {"q": "For 0 ≤ h < π/2, which fences hold?", "a": "sin h ≤ h ≤ tan h", "w": ["tan h ≤ h ≤ sin h", "sin h ≤ tan h ≤ h", "h ≤ sin h ≤ tan h"], "why": "Small-arc: the arc is an integral whose integrand is at least 1 and at most 1/cos h."}, {"q": "Can the slope of sin at 0 be used to find where sin h / h heads?", "a": "no: that slope is this very limit", "w": ["yes, by the quotient technique", "no: sin has no slope at 0", "yes"], "why": "It would be circular. The fences sin h ≤ h ≤ tan h come first, and the slope of sin is built on them."}, {"q": "As h heads to 0, to which real does (1 − cos h)/h head?", "a": "0", "w": ["to none", "1/2", "1"], "why": "Cosine-gap: multiply top and bottom by 1 + cos h, and the top becomes sin² h."}, {"q": "Is sin h = h for small h?", "a": "no: only the ratio sin h / h heads to 1", "w": ["yes", "yes, once h is less than 1/100", "no: sin h is more than h"], "why": "sin h ≤ h, and the two are equal only at h = 0."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["21g"]=(C["21g"]||[]).concat([{"q": "What is the slope of sin 2θ?", "a": "2 cos 2θ", "w": ["−2 cos 2θ", "cos 2θ", "2 cos θ"], "why": "The chain technique brings out the slope of the inside, 2."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["21h"]=(C["21h"]||[]).concat([{"q": "Given A, b and a, with A between 0 and π/2 and b sin A < a < b: how many triangles are there?", "a": "two", "w": ["one", "three", "none"], "why": "Two-triangles: the side a is long enough to reach the far line and short enough to reach it on both sides of the foot."}, {"q": "Area = ½ ab sin A: is that right?", "a": "no: the angle must be the one between the two sides, as in ½ ab sin C", "w": ["no: it is ½ ab cos A", "yes", "no: it is ab sin A"], "why": "Sine-area: half the product of two sides and the sine of the angle between them."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["21i"]=(C["21i"]||[]).concat([{"q": "Between which values does y = A sin θ + d swing?", "a": "d − |A| and d + |A|", "w": ["d and d + A", "−A and A", "A − d and A + d"], "why": "Wave-height: sin runs from −1 to 1, the pull by A makes that −|A| to |A|, and the lift by d moves the level."}, {"q": "A wave is highest at M and lowest at m. About which level does it swing?", "a": "(M + m)/2", "w": ["M − m", "(M − m)/2", "M + m"], "why": "Wave-from-readings: d = (M + m)/2 and A = (M − m)/2."}, {"q": "y = −3 sin θ: how far does it swing from its level?", "a": "3", "w": ["−3", "0", "6"], "why": "Wave-height: the swing is |A|. The minus turns the wave over."}, {"q": "sin(2θ + π/2) is sin(2θ) slid left by how much?", "a": "π/4", "w": ["2π", "π", "π/2"], "why": "Slide-inside: take the 2 out first. sin(2θ + π/2) = sin(2(θ + π/4))."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
